<?php
require __DIR__.'/includes/bootstrap.php';$user=music_require_page_user($mysqli);$uid=(int)$user['id'];$tracks=[];$stmt=$mysqli->prepare("SELECT id,title,genre,mood,status,current_stage,progress_percent,is_published,audio_media_id,cover_media_id,last_error,updated_at FROM music_ai_tracks WHERE owner_user_id=? AND status<>'DELETED' ORDER BY updated_at DESC");$stmt->bind_param('i',$uid);$stmt->execute();$rows=$stmt->get_result();while($row=$rows->fetch_assoc())$tracks[]=$row;$stmt->close();
?>
<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>eMusic Lite • Minhas músicas</title><link rel="stylesheet" href="assets/css/style.css"></head><body class="app-body"><div class="app"><aside class="sidebar"><div class="logo">eMusic Lite</div><nav><a href="dashboard.php">Início</a><a href="criar-musica.php">Criar com IA</a><a class="active" href="minhas-musicas.php">Minhas músicas</a><?php if(music_is_admin($uid)):?><a href="ai-agent.php">Agente musical</a><?php endif;?></nav><a class="logout" href="logout.php">Sair</a></aside>
<main class="main"><header class="topbar"><div><h1>Minhas músicas</h1><p>O progresso representa checkpoints concluídos no worker.</p></div><a class="button-link" href="criar-musica.php">Nova música</a></header><div id="musicMessage" class="alert" hidden></div>
<section class="project-list" id="projectList"><?php if(!$tracks):?><div class="panel"><p>Você ainda não criou uma música.</p></div><?php endif;?><?php foreach($tracks as $track):?><article class="project-card" data-track="<?=(int)$track['id']?>"><div class="project-cover"<?php if($track['cover_media_id']):?> style="background-image:url('api/music/media.php?id=<?=(int)$track['cover_media_id']?>&amp;v=<?=rawurlencode((string)$track['updated_at'])?>')"<?php endif;?>></div><div class="project-info"><div class="project-title-row"><div><h3><?=music_e($track['title'])?></h3><p><?=music_e($track['genre'])?> · <?=music_e($track['mood'])?></p></div><span class="status status-<?=strtolower(music_e($track['status']))?>"><?=music_e($track['status'])?></span></div><p class="stage"><?=music_e($track['current_stage'])?></p><div class="real-progress"><div style="width:<?=(int)$track['progress_percent']?>%"></div></div><small class="progress-label"><?=(int)$track['progress_percent']?>%</small><div class="project-actions"><?php if($track['audio_media_id']):?><button type="button" data-action="play" data-media="<?=(int)$track['audio_media_id']?>">Ouvir</button><?php endif;?><?php if($track['status']==='COMPLETED'&&!$track['is_published']):?><button type="button" data-action="publish">Publicar</button><?php endif;?><?php if(in_array($track['status'],['COMPLETED','FAILED'],true)):?><button type="button" class="secondary" data-action="edit">Editar dados</button><button type="button" class="secondary" data-action="regenerate">Gerar novamente</button><?php endif;?><button type="button" class="danger" data-action="delete">Excluir</button></div></div></article><?php endforeach;?></section><audio id="projectAudio" controls preload="metadata" hidden></audio></main></div><script>window.MUSIC_CSRF=<?=json_encode(music_csrf_token())?>;</script><script src="assets/js/my-music.js"></script></body></html>
